def calculate_fibonacci(n):
    """Calculates the nth Fibonacci number.
    Returns the Fibonacci number for valid non-negative integer inputs, otherwise returns None."""
    if not isinstance(n, int):
        return None
    if n < 0:
        return None
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

